	@Test
	void parallelOrderedRunPartitionsAlignDuplicateBoundaries() throws Exception {
		TestGraph graph = new TestGraph();
		graph.keyEnumerationDisabled = true;
		int roots = 30;
		for (int a = 1; a <= roots; a++) {
			graph.add(P1, a, 100L + a * 2L, 0);
			graph.add(P1, a, 101L + a * 2L, 0);
			graph.add(P3, a, 77, 0);
			graph.add(P3, a, 77, 5);
			if (a % 3 == 0) {
				graph.add(P3, a, 77, 9);
			}
		}
		MultiJoinPlan join = new MultiJoinPlan(new PatternPlan[] { pattern(0, P1, 1), unary(0, P3, 77) },
				new MaskedFilter[0]);
		String[] names = { "a", "b" };
		int[] groupSlots = { 0 };
		AggregateSpec[] aggregates = {
				AggregateSpec.slot("distinctB", 1, true, AggKind.COUNT),
				AggregateSpec.slot("countB", 1, false, AggKind.COUNT) };

		// Direct partition probe: cuts must tile the run and never split one neighbour's duplicate entries.
		RowState probeRow = row(graph.source(), names);
		LmdbNativePackedFtree.Plan probePlan = LmdbNativePackedFtree.Planner.plan(join, probeRow,
				demandedSlots(groupSlots, aggregates));
		assertNotNull(probePlan);
		try (LmdbNativePackedFtree.Runtime runtime = LmdbNativePackedFtree.Runtime.open(probePlan, probeRow)) {
			assertNotNull(runtime);
			assertTrue(runtime.roots instanceof LmdbNativePackedFtree.RunRootProducer,
					"without key enumeration this shape must seed from the constant-key P3 run");
			LmdbNativePackedFtree.RunRootProducer run = (LmdbNativePackedFtree.RunRootProducer) runtime.roots;
			LmdbNativePackedFtree.RootPartition[] partitions = runtime.planRootPartitions(12, 1L);
			assertNotNull(partitions, "a 70-entry run must partition at floor 1");
			assertTrue(partitions.length >= 2);
			assertEquals(0L, partitions[0].from);
			assertEquals(run.size, partitions[partitions.length - 1].to);
			for (int i = 0; i < partitions.length; i++) {
				if (i > 0) {
					assertEquals(partitions[i - 1].to, partitions[i].from, "partitions must tile the run");
				}
				long cut = partitions[i].from;
				if (cut > 0) {
					assertTrue(run.adjacency.neighborAt(run.handle, cut) != run.adjacency.neighborAt(run.handle,
							cut - 1), "an ordered cut must not split one neighbour's duplicates");
				}
			}
		}

		Map<String, String> legacy = collectJoin(graph, join, names, groupSlots, aggregates, false, null);
		SinkObservation observation = new SinkObservation();
		Map<String, String> parallel = collectParallel(graph, join, names, groupSlots, aggregates, observation);

		assertEquals(legacy, parallel);
		// a=3 carries root weight 3 (three contexts) over two distinct b values; a=1 carries weight 2.
		assertEquals("COUNT:count=2;COUNT:count=6", parallel.get("[3]"));
		assertEquals("COUNT:count=2;COUNT:count=4", parallel.get("[1]"));
		assertTrue(observation.sawChannelFreeState, "aligned ordered partitions keep the popcount path");
	}

