	@Test
	void parallelLeafGroupsMergeAcrossWorkers() throws Exception {
		TestGraph graph = new TestGraph();
		int roots = 600;
		// The root domain (600) stays the cheapest seed; b is 1200 distinct values and c folds b pairs 900 apart
		// onto one leaf value, so the same group key arrives from roots in far-apart partitions.
		for (int a = 1; a <= roots; a++) {
			long b0 = 2L * a;
			long b1 = 2L * a + 1;
			graph.add(P1, a, b0, 0);
			graph.add(P1, a, b1, 0);
			graph.add(P2, b0, 9_000L + (b0 % 900), 0);
			graph.add(P2, b1, 9_000L + (b1 % 900), 0);
		}
		MultiJoinPlan join = new MultiJoinPlan(new PatternPlan[] { pattern(0, P1, 1), pattern(1, P2, 2) },
				new MaskedFilter[0]);
		String[] names = { "a", "b", "c" };
		int[] groupSlots = { 2 };
		AggregateSpec[] aggregates = {
				AggregateSpec.slot("countA", 0, false, AggKind.COUNT),
				AggregateSpec.slot("distinctB", 1, true, AggKind.COUNT),
				AggregateSpec.slot("minB", 1, false, AggKind.MIN) };

		Map<String, String> legacy = collectJoin(graph, join, names, groupSlots, aggregates, false, null);
		Map<String, String> parallel = collectParallel(graph, join, names, groupSlots, aggregates, null);

		assertEquals(legacy, parallel);
		assertEquals(900, parallel.size());
	}

